<% elsif @game.open? %>
  <div class="screen__top">
    <span class="logo screen__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span><%= h @quiz.title %></span>
  </div>
  <div class="screen__body">
    <div class="stage-question__num"><%= h @progress %></div>
    <div class="stage-question__body"><%= h @question.body %></div>
