  </div>
  <div class="screen-controls">
    <div class="screen-controls__info">
      <a href="<%= moderate_quiz_path(@quiz) %>">← Back to quiz</a>
      <span class="muted"><%= h @quiz.title %></span>
    </div>
    <div class="buttons">
      <form action="<%= finish_moderate_quiz_game_path(@quiz, @game) %>" method="post">
        <input type="hidden" name="authenticity_token" value="<%= form_authenticity_token %>">
        <button type="submit" class="btn btn--pink btn--lg">Finish</button>
      </form>
    </div>
  </div>
<% elsif @game.closed? %>
  <div class="screen__top">
    <span class="logo screen__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span><%= h @quiz.title %></span>
  </div>
  <div class="screen__body">
    <div class="stage-question__num"><%= h @progress %></div>
    <div class="stage-question__body"><%= h @question.body %></div>
    <ol class="stage-options stage-options--results">
      <% total_answers = @answers_count.to_i %>
      <% @options.each_with_index do |opt, i| %>
        <% letter = ("A".ord + i).chr %>
        <% count = (@counts[opt.id] || @counts[opt.id.to_s] || 0).to_i %>
        <% share = total_answers > 0 ? (count * 100.0 / total_answers).round(1) : 0 %>
        <li class="stage-option <%= "is-correct" if opt.correct %>">
