          <span class="stage-option__title"><%= h opt.text %></span>
          <span class="stage-option__count"><%= count %></span>
          <% if opt.correct %>
            <span class="stage-option__mark">Correct</span>
          <% end %>
        </li>
      <% end %>
    </ol>
    <div class="answers-counter mt-2" id="answers-count"><%= h @answers_text %></div>
  </div>
  <div class="screen-controls">
    <div class="screen-controls__info">
      <a href="<%= moderate_quiz_path(@quiz) %>">← Back to quiz</a>
      <span class="muted"><%= h @quiz.title %></span>
    </div>
    <div class="buttons">
      <% if @is_last %>
        <form action="<%= end_quiz_moderate_quiz_game_path(@quiz, @game) %>" method="post">
          <input type="hidden" name="authenticity_token" value="<%= form_authenticity_token %>">
          <button type="submit" class="btn btn--pink btn--lg">End quiz</button>
        </form>
      <% else %>
        <form action="<%= next_question_moderate_quiz_game_path(@quiz, @game) %>" method="post">
          <input type="hidden" name="authenticity_token" value="<%= form_authenticity_token %>">
          <button type="submit" class="btn btn--pink btn--lg">Next</button>
        </form>
      <% end %>
    </div>
  </div>
<% else %>
  <div class="screen__top">
    <span class="logo screen__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span><%= h @quiz.title %></span>
  </div>
  <div class="screen__body">
    <div class="stage-question__num"><%= h @quiz.title %></div>
    <div class="stage-question__body">The quiz is over</div>
  </div>
  <div class="screen-controls">
    <div class="screen-controls__info">
      <a href="<%= moderate_quiz_path(@quiz) %>">← Back to quiz</a>
    </div>
    <div class="buttons"></div>
  </div>
<% end %>
